begin;
select no_plan();
insert into auth.users(id,raw_user_meta_data) values
 ('a8070000-0000-4000-8000-000000000001','{"handle":"identity_a","display_name":"Identity A"}'),
 ('a8070000-0000-4000-8000-000000000002','{"handle":"identity_b","display_name":"Identity B"}');
select ok((select avatar_id is null from public.profiles where handle='identity_a'),'existing profiles have no avatar; identity preserved');
select ok((select not public from storage.buckets where id='profile-avatars'),'avatar bucket private');
select ok((select relrowsecurity from pg_class where oid='public.catalog_identity_contributions'::regclass),'contribution RLS enabled');
select ok(not has_function_privilege('anon','public.contribute_catalog_identity(jsonb)','execute'),'anon cannot contribute');
select ok(not has_function_privilege('service_role','public.contribute_catalog_identity(jsonb)','execute'),'service role not granted contribution RPC');
select ok(has_function_privilege('authenticated','public.contribute_catalog_identity(jsonb)','execute'),'authenticated can contribute');
select is((select proconfig::text from pg_proc where oid='public.contribute_catalog_identity(jsonb)'::regprocedure),'{"search_path=\"\""}','empty hardened search path');
select ok((select prosecdef from pg_proc where oid='public.contribute_catalog_identity(jsonb)'::regprocedure),'privileged catalog creation narrowly definer');
set local role authenticated;
select set_config('request.jwt.claim.sub','a8070000-0000-4000-8000-000000000001',true);
create temporary table identity_result as select public.contribute_catalog_identity('{"submissionId":"b8070000-0000-4000-8000-000000000001","kind":"group","name":"Test Artist"}') result;
select is((select count(*)::int from public.catalog_identity_contributions),1,'first contribution created');
select is(public.contribute_catalog_identity('{"submissionId":"b8070000-0000-4000-8000-000000000001","kind":"group","name":"Test Artist"}'),(select result from identity_result),'committed result reused');
select is((select count(*)::int from public.catalog_identity_contributions),1,'retry no duplicate');
select throws_ok($$select public.contribute_catalog_identity('{"submissionId":"b8070000-0000-4000-8000-000000000001","kind":"group","name":"Changed Artist"}')$$,'22023',null,'key with changed details rejected');
select lives_ok($$select public.contribute_catalog_identity('{"submissionId":"b8070000-0000-4000-8000-000000000002","kind":"group","name":"test artist"}')$$,'new key legitimate same collector contribution');
select is((select count(*)::int from public.catalog_groups where slug='test-artist'),1,'normalized group deduplication');
select is((select name from public.catalog_groups where slug='test-artist'),'Test Artist','existing name not overwritten');
select is((select status::text from public.catalog_groups where slug='test-artist'),'community','not marked verified');
select lives_ok($$select public.contribute_catalog_identity(jsonb_build_object('submissionId','b8070000-0000-4000-8000-000000000003','kind','member','name','Test Member','groupId',(select result->>'groupId' from identity_result)))$$,'member requires selected real group');
select lives_ok($$select public.contribute_catalog_identity(jsonb_build_object('submissionId','b8070000-0000-4000-8000-000000000004','kind','member','name','test member','groupId',(select result->>'groupId' from identity_result)))$$,'member normalization deduplicates');
select is((select count(*)::int from public.catalog_members where normalized_name='test member'),1,'no duplicate member records');
select throws_ok($$select public.contribute_catalog_identity('{"submissionId":"bad","kind":"group","name":"Test"}')$$,'22023',null,'malformed key denied');
select throws_ok($$select public.contribute_catalog_identity('{"submissionId":"b8070000-0000-4000-8000-000000000005","kind":"member","name":"Test"}')$$,'22023',null,'missing group denied');
select throws_ok($$select public.contribute_catalog_identity('{"submissionId":"b8070000-0000-4000-8000-000000000005","kind":"group","name":"Test","userId":"other"}')$$,'22023',null,'caller cannot supply owner');
select throws_ok($$insert into public.catalog_identity_contributions(contributor_user_id,submission_id,kind,submitted_name,request,group_id) values(public.current_seoully_user_id(),gen_random_uuid(),'group','x','{}',gen_random_uuid())$$,'42501',null,'no direct contribution writes');
insert into storage.objects(bucket_id,name) select 'profile-avatars',public.current_seoully_user_id()::text||'/b8070000-0000-4000-8000-000000000001.jpg';
update public.profiles set avatar_id='b8070000-0000-4000-8000-000000000001' where user_id=public.current_seoully_user_id();
select is((select count(*)::int from storage.objects where bucket_id='profile-avatars'),1,'owner avatar upload/read');
insert into storage.objects(bucket_id,name) select 'profile-avatars',public.current_seoully_user_id()::text||'/b8070000-0000-4000-8000-000000000002.jpg';
select set_config('request.jwt.claim.sub','a8070000-0000-4000-8000-000000000002',true);
select is((select count(*)::int from public.catalog_identity_contributions),0,'other collector cannot retrieve private contribution history');
select lives_ok($$select public.contribute_catalog_identity('{"submissionId":"b8070000-0000-4000-8000-000000000001","kind":"group","name":"Test Artist"}')$$,'same textual key other collector independent');
select is((select count(*)::int from public.catalog_identity_contributions),1,'other collector own attribution');
select is((select count(*)::int from storage.objects where bucket_id='profile-avatars'),1,'other viewer only published avatar, not unpublished photo');
with changed as(update public.profiles set avatar_id=null where handle='identity_a' returning 1)
select is((select count(*)::int from changed),0,'other collector cannot replace avatar');
select throws_ok($$insert into storage.objects(bucket_id,name) select 'profile-avatars',user_id::text||'/b8070000-0000-4000-8000-000000000009.jpg' from public.profiles where handle='identity_a'$$,'42501',null,'cannot upload into another collector path');
reset role;
set local role anon;
select is((select count(*)::int from storage.objects where bucket_id='profile-avatars'),1,'public avatar available, unpublished avatar stays private');
select throws_ok($$select public.contribute_catalog_identity('{}')$$,'42501',null,'anonymous contribution denied');
reset role;
select is((select count(*)::int from public.holdings),0,'identity contributions do not create Holdings');
select is((select count(*)::int from public.rooms),0,'Room unchanged');
select * from finish();
rollback;
